import type { Actor, Catalogs, DeviceFeature, DevicePreset, DeviceRecord, DeviceType, EnforcementRequest, FeatureHistoryEvent, JsonObject, ObjectRecord, ObjectType, SessionContext } from "@/features/device-management/types/device-management.types";
import { asDeviceId, asEnforcementRequestId, asObjectId, asPresetId } from "@/features/device-management/types/device-management.types";

export const requester: Actor = { id: "actor-requester", displayName: "Kỹ thuật viên Minh" };
export const approver: Actor = { id: "actor-approver", displayName: "Quản trị viên Lan" };
export const adminSession: SessionContext = { actor: approver, permissions: ["object.read", "object.write", "object.delete", "device.read", "device.write", "device.delete", "feature.write", "enforcement.request", "enforcement.approve", "preset.write", "preset.delete", "audit.read"] };
export const requesterSession: SessionContext = { actor: requester, permissions: ["object.read", "object.write", "device.read", "device.write", "feature.write", "enforcement.request", "preset.write", "preset.delete"] };
export const readonlySession: SessionContext = { actor: { id: "actor-readonly", displayName: "Người xem" }, permissions: ["object.read", "device.read"] };

const cameraFeature = { id: "feature-lpr", code: "lpr", name: "Nhận diện biển số", isEnforcement: true, defaultConfig: {} satisfies JsonObject };
const ptzFeature = { id: "feature-ptz", code: "ptz", name: "Điều khiển PTZ", isEnforcement: false, defaultConfig: {} satisfies JsonObject };
const gpsFeature = { id: "feature-gps", code: "gps", name: "Theo dõi GPS", isEnforcement: false, defaultConfig: {} satisfies JsonObject };
export const objectTypes: readonly ObjectType[] = [{ id: "junction", code: "junction", name: "Nút giao" }, { id: "depot", code: "depot", name: "Bến xe" }];
export const deviceTypes: readonly DeviceType[] = [
  { id: "lpr-camera", code: "lpr_camera", name: "Camera LPR PTZ", iconId: "camera", uiPanel: "camera", capabilities: [cameraFeature, ptzFeature], ptzConstraints: { pan: { min: -180, max: 180, step: 0.1 }, tilt: { min: -90, max: 90, step: 0.1 }, zoom: { min: 1, max: 40, step: 0.1 } } },
  { id: "bus-gps", code: "bus_gps", name: "GPS xe buýt", iconId: "bus", uiPanel: "fleet", capabilities: [gpsFeature], ptzConstraints: null },
];
export const catalogs: Catalogs = { objectTypes, deviceTypes, objectStatuses: ["active", "inactive"], deviceStatuses: ["active", "maintenance", "inactive"] };

export function createObject(index = 1): ObjectRecord { const type = objectTypes[index % objectTypes.length]!; return { id: asObjectId(`object-${String(index).padStart(5, "0")}`), code: `OBJ-${String(index).padStart(5, "0")}`, name: `Vị trí ${index}`, objectType: type, location: { type: "Point", coordinates: [106.65 + (index % 100) * 0.001, 10.75 + (index % 100) * 0.001] }, status: "active", attrs: { district: "Quận 1" }, version: 1, createdAt: "2026-09-05T00:00:00.000Z", updatedAt: "2026-09-05T00:00:00.000Z", deletedAt: null }; }
export function createDevice(index = 1, object = createObject(index)): DeviceRecord { const deviceType = deviceTypes[index % deviceTypes.length]!; return { id: asDeviceId(`device-${String(index).padStart(5, "0")}`), code: `DEV-${String(index).padStart(5, "0")}`, name: `${deviceType.name} ${index}`, serial: `SN-${index}`, deviceType, object: { id: object.id, code: object.code, name: object.name, objectType: object.objectType }, config: {}, status: "active", lastSeenAt: "2026-09-05T00:00:00.000Z", version: 1, createdAt: "2026-09-05T00:00:00.000Z", updatedAt: "2026-09-05T00:00:00.000Z", deletedAt: null }; }
export function createCatalogDevices(count = 2_000): DeviceRecord[] { const objects = Array.from({ length: Math.min(count, 500) }, (_, index) => createObject(index + 1)); return Array.from({ length: count }, (_, index) => createDevice(index + 1, objects[index % objects.length]!)); }
export function featuresFor(device: DeviceRecord): DeviceFeature[] { return device.deviceType.capabilities.map((feature) => ({ deviceId: device.id, feature, isEnabled: false, config: feature.defaultConfig, pendingRequest: null, version: 1, etag: `\"feature-${device.id}-${feature.code}-1\"`, updatedAt: device.updatedAt, updatedBy: null })); }
export function createPreset(deviceId = asDeviceId("device-00002")): DevicePreset { return { id: asPresetId("preset-1"), deviceId, presetNo: 1, name: "Làn chính", pan: 0, tilt: -10, zoom: 4, enforcementZone: { type: "Polygon", coordinates: [[[106.7, 10.77], [106.701, 10.77], [106.701, 10.771], [106.7, 10.77]]] }, laneLabel: "Làn 1", approach: "Bắc", isCalibrated: true, calibratedAt: "2026-09-05T00:00:00.000Z", calibratedBy: approver, version: 1, createdAt: "2026-09-05T00:00:00.000Z", updatedAt: "2026-09-05T00:00:00.000Z", deletedAt: null }; }
export function createEnforcementRequest(device: DeviceRecord): EnforcementRequest { const feature = device.deviceType.capabilities.find((item) => item.isEnforcement) ?? cameraFeature; return { id: asEnforcementRequestId("request-1"), deviceId: device.id, feature, requestedConfig: {}, reason: "Kích hoạt kiểm tra", status: "pending", requestedAt: "2026-09-05T00:00:00.000Z", requestedBy: requester, decidedAt: null, decidedBy: null, decisionNote: null, version: 1, etag: "\"request-1-v1\"" }; }
export function createHistory(device: DeviceRecord): FeatureHistoryEvent[] { return [{ id: "history-1", deviceId: device.id, feature: device.deviceType.capabilities[0]!, eventType: "disabled", before: null, after: { is_enabled: false }, reason: null, approvalRequestId: null, validFrom: "2026-09-05T00:00:00.000Z", actor: approver }]; }
